import numpy as np
import pandas as pd

def rolling_vol(r, w, annualise=True):
    s = pd.Series(r, dtype=float)
    vol = s.rolling(w).std()
    if annualise:
        vol = vol * np.sqrt(252)
    return vol.to_numpy()

import numpy as np

def vol_range(r, w):
    v = rolling_vol(r, w)
    v = v[~np.isnan(v)]
    return (round(float(v.min()), 4), round(float(v.max()), 4))
